 on('#connection-type',e=>{modal.draft={name:$('#account-form [name=name]').value,subaccount:Number($('#account-form [name=subaccount]').value)};modal.connectionType=e.target.value;render()},'change');
 on('#llm-provider',e=>{const f=$('#agent-form');modal.draft={name:f.querySelector('[name=name]').value,accountId:f.querySelector('[name=accountId]').value};modal.provider=e.target.value;render()},'change');
 
 const accountForm=$('#account-form');if(accountForm)accountForm.onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(accountForm)),a=state.accounts.find(x=>x.id===modal.id);v.id=a?.id;v.connectionType=v.connectionType||a.connectionType;v.subaccount=Number(v.subaccount??a?.subaccount??0);v.confirmLive=v.confirmLive==='on';if(v.identifier||v.private_key)v.credentials={key_id:v.identifier,private_key:v.private_key};delete v.identifier;delete v.private_key;const fromAgent=modal?.reason==='agent';const result=await api('account-save',v);if(!error){modal=null;render()}if(result?.accountId){await api('account-test',{id:result.accountId});const saved=state.accounts.find(x=>x.id===result.accountId);if(saved?.status==='connected'){if(fromAgent){modal={type:'agent'};render()}}else{page='Connected Accounts';render()}}};
 const agentForm=$('#agent-form');if(agentForm)agentForm.onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(agentForm)),a=state.agentConfigs.find(x=>x.id===modal.id);v.id=a?.id;v.accountId=v.accountId||a?.accountId;modal.draft={name:v.name,provider:v.provider,model:v.model,accountId:v.accountId};const result=await api('agent-save',v);if(!error&&result){agent=result.agentId;page='Selected Trading Agent';modal={type:'mandate',id:agent};render()}};
 const mandateForm=$('#mandate-setup');if(mandateForm){const ma=state.agentConfigs.find(x=>x.id===modal.id),acct=state.accounts.find(x=>x.id===ma?.accountId);sliderBind(mandateForm,state.rulesCatalog.mandateFields.filter(f=>f.unit!=='boolean'),()=>acctValue(acct?.balance),v=>{modal.draft={...(modal.draft||{}),...v}});mandateForm.onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(mandateForm));const mandate={autoLimitPercent:Number(v.autoLimitPercent),dailyCapPercent:Number(v.dailyCapPercent),minimumPercent:Number(v.minimumPercent),newMarketApproval:v.newMarketApproval==='on'};modal.draft=mandate;await api('mandate-save',{id:modal.id,mandate});if(!error){modal=null;render()}}};
